DECLARE @dataset BIGINT=(SELECT TOP 1 dataset_id FROM platform.dataset WHERE dataset_code=N'KIDS_FILE_RESOURCE');
DECLARE @measure BIGINT=(SELECT TOP 1 measure_id FROM platform.measure WHERE measure_code=N'OBS_VALUE');
INSERT platform.metric(metric_code,source_dataset_id,measure_id,aggregation,status)
SELECT CONCAT(N'KIDS_',v.id),@dataset,@measure,N'SUM',N'PROVISIONAL_APPROVED' FROM (VALUES
(N'ABORTIONS_COUNT'),(N'MALIGNANT_NEOPLASM_NEW_CASES'),(N'SEXUALLY_TRANSMITTED_DISEASE_NEW_CASES'),(N'DIABETES_MELLITUS_NEW_CASES'),(N'RESPIRATORY_TUBERCULOSIS_CASES'),(N'TUBERCULOUS_MENINGITIS_CASES'),(N'MUSCULOSKELETAL_TUBERCULOSIS_CASES'),(N'INFECTIOUS_PARASITIC_DISEASE_NEW_CASES'),(N'BLOOD_DISEASE_NEW_CASES'),(N'ENDOCRINE_METABOLIC_DISEASE_NEW_CASES'),(N'MENTAL_BEHAVIOURAL_DISORDER_NEW_CASES'),(N'NERVOUS_SYSTEM_DISEASE_NEW_CASES'),(N'EYE_ADNEXA_DISEASE_NEW_CASES'),(N'EAR_MASTOID_DISEASE_NEW_CASES'),(N'CIRCULATORY_DISEASE_NEW_CASES'),(N'RESPIRATORY_DISEASE_NEW_CASES'),(N'DIGESTIVE_DISEASE_NEW_CASES'),(N'SKIN_SUBCUTANEOUS_DISEASE_NEW_CASES'),(N'MUSCULOSKELETAL_DISEASE_NEW_CASES'),(N'UROGENITAL_DISEASE_NEW_CASES'),(N'CONGENITAL_MALFORMATION_NEW_CASES'),(N'DISABILITY_SOCIAL_PACKAGE_RECIPIENTS'),(N'SURVIVOR_SOCIAL_PACKAGE_RECIPIENTS'),(N'SUBSISTENCE_ALLOWANCE_BENEFICIARIES'),(N'PLANNED_OUTPATIENT_REGISTERED_PERSONS'),(N'CHRONIC_MEDICINE_PROGRAM_BENEFICIARIES'),(N'ADOPTED_CHILDREN'),(N'CHILDREN_GRANTED_ADOPTION_STATUS'),(N'INTERNALLY_DISPLACED_PERSONS'),(N'LABOUR_FORCE_POPULATION'),(N'RESIDENT_VISITORS_MONTHLY_AVERAGE'),(N'DOMESTIC_VISITS_MONTHLY_AVERAGE'),(N'AVERAGE_NIGHTS_PER_VISIT'),(N'MATERNAL_MORTALITY_RATIO'),(N'HIV_INCIDENCE_RATE'),(N'ANAEMIA_PREVALENCE'),(N'SUICIDES_COUNT'),(N'SUICIDE_MORTALITY_RATE'),(N'DAILY_INTERNET_USE_SHARE'),(N'RECENT_COMPUTER_USE_SHARE'),(N'MOBILE_PHONE_USE_SHARE'),(N'LITERACY_RATE'),(N'EARLY_EDUCATION_LEAVERS_RATE'))v(id)
WHERE NOT EXISTS(SELECT 1 FROM platform.metric m WHERE m.metric_code=CONCAT(N'KIDS_',v.id));
